expression.value:
@and(
    greaterOrEquals(pipeline().parameters.p_copy_parallel_copies, 0),
    or(
        equals(
            toUpper(pipeline().parameters.p_copy_partition_option),
            'NONE'
        ),
        or(
            and(
                equals(
                    toUpper(pipeline().parameters.p_copy_partition_option),
                    'DYNAMIC_RANGE'
                ),
                not(empty(pipeline().parameters.p_copy_partition_column))
            ),
            equals(
                toUpper(pipeline().parameters.p_copy_partition_option),
                'PHYSICAL_PARTITIONS'
            )
        )
    )
)
